import React,{useState} from 'react';
import Panel from '@project/Panel';
export default function Board({state='ready'}){const [lane,setLane]=useState('Ready');const [query,setQuery]=useState('');if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
return <div className="shell"><span className="eyebrow">Delivery workspace / Reference interaction</span><h1>Give important work a clear path.</h1><p>Shape the next step before you add another meeting.</p><label>Filter work <input aria-label="Filter work" value={query} onChange={e=>setQuery(e.currentTarget.value)}/></label><div className="grid"><Panel title="Ready"><span className="tag">02 priorities</span>{'Launch checklist'.toLowerCase().includes(query.toLowerCase())&&<article><h3>Launch checklist</h3><p>Confirm ownership and close the last unknowns.</p><button id="move" className="btn" onClick={()=>setLane('In progress')}>Start this task</button></article>}</Panel><Panel title="In progress"><p id="result">{lane==='In progress'?'Launch checklist · In progress':'No reference task is active yet.'}</p></Panel><Panel title="Complete"><p>Only completed work belongs here.</p></Panel></div><p className="muted spacer">Reference board. Changes are local and do not imply a project API write.</p></div>;}
